def resolve_suite(p)
    return ['ed25519', nil] unless p.key?('alg')

    alg = p['alg']
    return [nil, "'alg' must be a string"] unless alg.is_a?(String)
    return [nil, "unknown signature alg '#{alg}'"] unless SIG_SUITES.key?(alg)

    [alg, nil]
  end

